const llmResponse = $input.first().json;
const routeData = $('Route Mode').first().json;

// Parser la réponse LLM
let improvedAppJs = null;
try {
  let content = llmResponse.choices?.[0]?.message?.content;
  if (typeof content === 'string') {
    content = content.replace(/```json\n?/g, '').replace(/```\n?/g, '').trim();
    const parsed = JSON.parse(content);
    if (parsed.app_js && typeof parsed.app_js === 'string' && parsed.app_js.length > 100) {
      // Valider que les fonctions clés sont préservées
      const required = ['loadItems', 'showFeedback', 'escapeHtml', 'addEventListener'];
      const allPresent = required.every(fn => parsed.app_js.includes(fn));
      if (allPresent) {
        improvedAppJs = parsed.app_js;
        console.log('LLM Frontend amelioration appliquee');
      } else {
        console.log('LLM output incomplet — fonctions manquantes, fallback deterministe');
      }
    }
  }
} catch(e) {
  console.log('Erreur parse LLM Frontend:', e.message, '— fallback deterministe');
}

const inp = routeData._inp || {};
return [{
  json: {
    ...inp,
    mode: 'deterministic',
    html_skeleton: routeData._html_skeleton || '',
    css_content:   routeData._css_content   || '',
    _login_html:   routeData._login_html || (inp && inp._login_html) || '',
    _app_js:       improvedAppJs || routeData._app_js_base || ''
  }
}];

var items = $input.all();
var inputJson = items[0].json;
var data = inputJson;
if (inputJson.body !== undefined) {
  var rawBody = inputJson.body;
  if (typeof rawBody === 'string') {
    rawBody = rawBody.replace(/^=+/, '').trim();
    try { data = JSON.parse(rawBody); } catch(e) { data = inputJson; }
  } else if (typeof rawBody === 'object') { data = rawBody; }
}

var userRequest = data.userRequest || data.prompt || data.description || data.specs;
if (!userRequest) {
  try { const wh=$('Webhook').first().json; const wb=(wh.body&&typeof wh.body==='object')?wh.body:wh; userRequest=wb.userRequest||wb.prompt||wb.description; } catch(e) {}
}
if (!userRequest && data.architecture) {
  userRequest = 'Frontend pour : ' + (data.architecture.mvp_scope || JSON.stringify(data.architecture));
}
if (!userRequest) throw new Error('userRequest manquant. Clés: ' + Object.keys(data).join(', '));

var endpoints    = data.priority_endpoints || data.architecture?.priority_endpoints || [];
var stores       = data.stores || data.architecture?.stores || {};
var mvpScope     = data.mvp_scope || data.architecture?.mvp_scope || '';
var projectName  = data.project_name || data.architecture?.project_name || '';
var dataModel    = data.data_model || data.architecture?.data_model || {};
var resourceName = Object.keys(dataModel)[0] || 'items';
var resourceFields = dataModel[resourceName] || {};
var displayFields = Object.keys(resourceFields).filter(function(k){ return k !== 'id' && k !== 'created_at' && k !== 'updated_at'; });

var postEp    = endpoints.find(function(ep){ return ep.method === 'POST'; });
var getListEp = endpoints.find(function(ep){ return ep.method === 'GET' && !ep.path.includes(':') && ep.path !== '/health'; });
var pageTitle = projectName ? projectName : (mvpScope ? mvpScope.substring(0, 60) : resourceName.charAt(0).toUpperCase() + resourceName.slice(1) + ' Manager');

// Logo dynamique
var logoEmoji = '\u26a1';
var pl = (mvpScope || resourceName).toLowerCase();
if (pl.includes('trajet') || pl.includes('trip') || pl.includes('voyage')) logoEmoji = '\u2708\ufe0f';
else if (pl.includes('t\u00e2che') || pl.includes('task') || pl.includes('todo')) logoEmoji = '\u2705';
else if (pl.includes('contact') || pl.includes('user') || pl.includes('client')) logoEmoji = '\ud83d\udc65';
else if (pl.includes('produit') || pl.includes('product') || pl.includes('shop')) logoEmoji = '\ud83d\udecd\ufe0f';
else if (pl.includes('commande') || pl.includes('order')) logoEmoji = '\ud83d\udce6';
else if (pl.includes('message') || pl.includes('chat')) logoEmoji = '\ud83d\udcac';
else if (pl.includes('crime') || pl.includes('signalement') || pl.includes('incident') || pl.includes('urgence')) logoEmoji = '\ud83d\udea8';
  else if (pl.includes('koli') || pl.includes('bagage') || pl.includes('kilo')) logoEmoji = '\ud83c\udfa2';
else if (pl.includes('restaurant') || pl.includes('food') || pl.includes('menu')) logoEmoji = '\ud83c\udf7d\ufe0f';
else if (pl.includes('event') || pl.includes('\u00e9v\u00e9nement')) logoEmoji = '\ud83d\udcc5';

// ── Palette de couleurs par domaine métier (déterministe, sur le même modèle que le logo) ──
// Chaque domaine a des couleurs primaire/secondaire/succès/danger cohérentes avec son ambiance.
// Une palette générique neutre s'applique si aucun mot-clé ne matche (garantit un rendu correct
// même sur un domaine totalement imprévu — condition testée en soutenance).
var theme = { primary: '#6366f1', primaryDark: '#4f46e5', secondary: '#06b6d4', success: '#10b981', danger: '#ef4444', warning: '#f59e0b' };
if (pl.includes('crime') || pl.includes('signalement') || pl.includes('incident') || pl.includes('urgence') || pl.includes('s\u00e9curit\u00e9') || pl.includes('securite')) {
  theme = { primary: '#dc2626', primaryDark: '#991b1b', secondary: '#1e293b', success: '#16a34a', danger: '#b91c1c', warning: '#d97706' };
} else if (pl.includes('koli') || pl.includes('bagage') || pl.includes('kilo') || pl.includes('trajet') || pl.includes('livraison') || pl.includes('transport') || pl.includes('logistique')) {
  theme = { primary: '#0891b2', primaryDark: '#0e7490', secondary: '#f97316', success: '#10b981', danger: '#ef4444', warning: '#f59e0b' };
} else if (pl.includes('sant\u00e9') || pl.includes('sante') || pl.includes('m\u00e9dic') || pl.includes('medic') || pl.includes('patient') || pl.includes('clinique')) {
  theme = { primary: '#0d9488', primaryDark: '#0f766e', secondary: '#38bdf8', success: '#22c55e', danger: '#ef4444', warning: '#f59e0b' };
} else if (pl.includes('finance') || pl.includes('paiement') || pl.includes('facture') || pl.includes('banque') || pl.includes('budget') || pl.includes('comptab')) {
  theme = { primary: '#1e40af', primaryDark: '#1e3a8a', secondary: '#ca8a04', success: '#16a34a', danger: '#dc2626', warning: '#d97706' };
} else if (pl.includes('produit') || pl.includes('commande') || pl.includes('shop') || pl.includes('boutique') || pl.includes('vente')) {
  theme = { primary: '#7c3aed', primaryDark: '#6d28d9', secondary: '#ec4899', success: '#10b981', danger: '#ef4444', warning: '#f59e0b' };
} else if (pl.includes('restaurant') || pl.includes('food') || pl.includes('menu')) {
  theme = { primary: '#ea580c', primaryDark: '#c2410c', secondary: '#65a30d', success: '#16a34a', danger: '#dc2626', warning: '#eab308' };
} else if (pl.includes('t\u00e2che') || pl.includes('tache') || pl.includes('task') || pl.includes('todo') || pl.includes('projet')) {
  theme = { primary: '#4338ca', primaryDark: '#3730a3', secondary: '#0ea5e9', success: '#10b981', danger: '#ef4444', warning: '#f59e0b' };
}
// Sinon : palette générique par défaut définie plus haut (indigo neutre) — cas TrocSavoir-like

// ── HTML via concaténation (pas de template literal pour éviter les conflits) ──
var html = '';
html += '<!DOCTYPE html>\n';
html += '<html lang="fr">\n';
html += '<head>\n';
html += '  <meta charset="UTF-8">\n';
html += '  <meta name="viewport" content="width=device-width, initial-scale=1.0">\n';
html += '  <title>' + pageTitle + '</title>\n';
html += '  <link rel="stylesheet" href="style.css">\n';
html += '</head>\n';
html += '<body>\n';
html += '  <header class="app-header">\n';
html += '    <div class="header-content">\n';
html += '      <div class="logo">' + logoEmoji + '</div>\n';
html += '      <h1>' + pageTitle + '</h1>\n';
html += '    </div>\n';
html += '  </header>\n';
html += '  <main class="app-main">\n';

if (postEp) {
  html += '    <section class="card" id="section-create">\n';
  html += '      <h2 class="card-title">\u270f\ufe0f ' + postEp.description + '</h2>\n';
  html += '      <form id="form-create" class="create-form" method="post" onsubmit="return false;" autocomplete="off">\n';
  displayFields.forEach(function(f) {
    var label = f.charAt(0).toUpperCase() + f.slice(1).replace(/_/g, ' ');
    var type  = resourceFields[f] === 'boolean' ? 'checkbox' : (f.includes('kilo') || f.includes('price') || f.includes('prix') || f.includes('montant') ? 'number' : 'text');
    html += '        <div class="form-group">\n';
    html += '          <label for="field-' + f + '">' + label + '</label>\n';
    if (type === 'checkbox') {
      html += '          <input type="checkbox" id="field-' + f + '" name="' + f + '" class="form-check">\n';
    } else {
      html += '          <input type="' + type + '" id="field-' + f + '" name="' + f + '" placeholder="Entrez ' + label.toLowerCase() + '" class="form-input"' + (type === 'text' && (f.includes('password') || f.includes('token') || f.includes('secret') || f.includes('key')) ? ' type="password" autocomplete="new-password"' : '') + ' required>\n';
    }
    html += '        </div>\n';
  });
  html += '        <button type="submit" class="btn btn-primary">Cr\u00e9er</button>\n';
  html += '      </form>\n';
  html += '      <div id="feedback-create" class="feedback"></div>\n';
  html += '    </section>\n\n';
}

if (getListEp) {
  html += '    <section class="card" id="section-list">\n';
  html += '      <div class="section-header">\n';
  html += '        <h2 class="card-title">\ud83d\udccb ' + (getListEp.description || 'Liste') + '</h2>\n';
  html += '        <button onclick="loadItems()" class="btn btn-secondary">\u21bb Actualiser</button>\n';
  html += '      </div>\n';
  html += '      <div id="items-list" class="items-list"><div class="loading">Chargement...</div></div>\n';
  html += '    </section>\n';
}

html += '  </main>\n';
html += '  <script src="app.js"></script>\n';
html += '</body>\n</html>';

// CSS déterministe
var css = '/* FILE: frontend/style.css */\n';
css += ':root {\n';
css += '  --primary: ' + theme.primary + '; --primary-dark: ' + theme.primaryDark + '; --secondary: ' + theme.secondary + ';\n';
css += '  --success: ' + theme.success + '; --danger: ' + theme.danger + '; --warning: ' + theme.warning + ';\n';
css += '  --bg: #f0f2f5; --surface: #ffffff; --border: #e5e7eb;\n';
css += '  --text: #1f2937; --muted: #6b7280;\n';
css += '  --shadow: 0 4px 6px -1px rgba(0,0,0,0.1);\n';
css += '}\n';
css += '* { box-sizing: border-box; margin: 0; padding: 0; }\n';
css += 'body { background: var(--bg); color: var(--text); font-family: "Segoe UI", system-ui, sans-serif; min-height: 100vh; }\n';
css += '.app-header { background: linear-gradient(135deg, var(--primary) 0%, var(--secondary) 100%); color: white; padding: 20px 32px; box-shadow: var(--shadow); }\n';
css += '.header-content { max-width: 1100px; margin: 0 auto; display: flex; align-items: center; gap: 14px; }\n';
css += '.logo { width: 42px; height: 42px; background: rgba(255,255,255,0.2); border-radius: 10px; display: flex; align-items: center; justify-content: center; font-size: 20px; }\n';
css += '.app-header h1 { font-size: 20px; font-weight: 700; }\n';
css += '.app-main { max-width: 1100px; margin: 0 auto; padding: 28px 20px; display: flex; flex-direction: column; gap: 20px; }\n';
css += '.card { background: var(--surface); border-radius: 14px; padding: 24px; box-shadow: var(--shadow); border: 1px solid var(--border); }\n';
css += '.card-title { font-size: 16px; font-weight: 600; margin-bottom: 18px; }\n';
css += '.section-header { display: flex; align-items: center; justify-content: space-between; margin-bottom: 18px; }\n';
css += '.section-header .card-title { margin-bottom: 0; }\n';
css += '.create-form { display: grid; grid-template-columns: repeat(auto-fit, minmax(200px, 1fr)); gap: 14px; align-items: end; }\n';
css += '.form-group { display: flex; flex-direction: column; gap: 5px; }\n';
css += '.form-group label { font-size: 12px; font-weight: 600; color: var(--muted); text-transform: uppercase; letter-spacing: 0.5px; }\n';
css += '.form-input { padding: 10px 14px; border: 2px solid var(--border); border-radius: 8px; font-size: 14px; color: var(--text); transition: border-color 0.2s; outline: none; background: var(--bg); }\n';
css += '.form-input:focus { border-color: var(--primary); box-shadow: 0 0 0 3px rgba(124,58,237,0.1); background: white; }\n';
css += '.btn { padding: 10px 20px; border: none; border-radius: 8px; font-size: 14px; font-weight: 600; cursor: pointer; transition: all 0.2s; display: inline-flex; align-items: center; gap: 6px; }\n';
css += '.btn-primary { background: var(--primary); color: white; }\n';
css += '.btn-primary:hover { background: var(--primary-dark); transform: translateY(-1px); box-shadow: 0 4px 12px rgba(124,58,237,0.3); }\n';
css += '.btn-secondary { background: var(--bg); color: var(--muted); border: 1px solid var(--border); }\n';
css += '.btn-secondary:hover { background: var(--border); color: var(--text); }\n';
css += '.btn-danger { background: transparent; color: var(--danger); border: 1px solid var(--danger); padding: 6px 12px; font-size: 12px; border-radius: 6px; cursor: pointer; }\n';
css += '.btn-danger:hover { background: var(--danger); color: white; }\n';
css += '.btn-edit { background: transparent; color: var(--secondary); border: 1px solid var(--secondary); padding: 6px 12px; font-size: 12px; border-radius: 6px; cursor: pointer; }\n';
css += '.btn-edit:hover { background: var(--secondary); color: white; }\n';
css += '.feedback { margin-top: 12px; padding: 10px 16px; border-radius: 8px; font-size: 13px; font-weight: 500; display: none; }\n';
css += '.feedback.show { display: block; }\n';
css += '.feedback.success { background: rgba(16,185,129,0.1); color: var(--success); border: 1px solid rgba(16,185,129,0.3); }\n';
css += '.feedback.error { background: rgba(239,68,68,0.1); color: var(--danger); border: 1px solid rgba(239,68,68,0.3); }\n';
css += '.items-list { display: flex; flex-direction: column; gap: 10px; }\n';
css += '.item-card { background: var(--bg); border: 1px solid var(--border); border-radius: 10px; padding: 16px 20px; display: flex; align-items: center; justify-content: space-between; transition: border-color 0.2s; }\n';
css += '.item-card:hover { border-color: var(--primary); box-shadow: 0 2px 8px rgba(124,58,237,0.1); }\n';
css += '.item-info { display: flex; flex-direction: column; gap: 4px; }\n';
css += '.item-title { font-weight: 600; font-size: 15px; }\n';
css += '.item-meta { font-size: 12px; color: var(--muted); }\n';
css += '.item-actions { display: flex; gap: 8px; }\n';
css += '.loading { color: var(--muted); font-size: 13px; padding: 20px; text-align: center; }\n';
css += '.empty-state { color: var(--muted); font-size: 13px; padding: 40px; text-align: center; }\n';
css += '@media (max-width: 600px) { .create-form { grid-template-columns: 1fr; } .item-card { flex-direction: column; align-items: flex-start; gap: 10px; } }\n';

// Routes et IDs pour le LLM
var routesDoc = '\nROUTES BACKEND EXACTES :\n';
endpoints.forEach(function(ep) { routesDoc += ep.method + ' ' + ep.path + ' -> ' + ep.description + '\n'; });

var fieldsDoc = '\nCHAMPS : ' + JSON.stringify(resourceFields) + '\n';

var idsDoc = '\nIDs HTML OBLIGATOIRES dans app.js :\n';
idsDoc += '- document.getElementById("form-create") -> formulaire\n';
idsDoc += '- document.getElementById("feedback-create") -> messages\n';
idsDoc += '- document.getElementById("items-list") -> liste\n';
displayFields.forEach(function(f) { idsDoc += '- document.getElementById("field-' + f + '") -> champ ' + f + '\n'; });

var systemPrompt = 'Tu es un développeur JavaScript frontend expert.\n\n' +
'TACHE : Générer UNIQUEMENT le fichier app.js.\n\n' +
'REGLE ABSOLUE : Retourner UNIQUEMENT un JSON valide.\n' +
'FORMAT :\n' +
'{\n' +
'  "agent": "frontend",\n' +
'  "files": [\n' +
'    {"path": "frontend/app.js", "content": "// FILE: frontend/app.js\\n..."}\n' +
'  ]\n' +
'}\n\n' +
'REGLES OBLIGATOIRES :\n' +
'1. event.preventDefault() sur le submit du formulaire (OBLIGATOIRE)\n' +
'2. Utiliser document.getElementById("form-create") pour le formulaire\n' +
'3. Utiliser document.getElementById("items-list") pour la liste\n' +
'4. Utiliser document.getElementById("feedback-create") pour les messages\n' +
'5. Utiliser document.getElementById("field-NOM") pour chaque champ\n' +
'6. Apres creation reussie : appeler loadItems() ET form.reset()\n' +
'7. Feedback : ajouter classes "show success" ou "show error", retirer apres 3s\n' +
'8. loadItems() appelee au DOMContentLoaded\n' +
'9. async/await + try/catch sur tous les fetch()\n' +
'10. Boutons edit et delete sur chaque item dans la liste\n' +
'11. ECHAPPEMENT OBLIGATOIRE : dans toute chaine JS delimitee par des guillemets doubles, ' +
'echapper systematiquement chaque guillemet double interne avec \\". ' +
'INTERDIT (invalide, provoque un SyntaxError) : "<option value=" + id + "">" ' +
'CORRECT (obligatoire) : "<option value=\\"" + id + "\\">" ' +
'Cette regle s\'applique a TOUTE construction de balise HTML contenant un attribut entre guillemets ' +
'(value=, class=, id=, etc.) a l\'interieur d\'une chaine JS a guillemets doubles.';

return [{
  json: {
    systemPrompt: systemPrompt,
    userPrompt: 'Genere app.js pour :\n' + userRequest + routesDoc + fieldsDoc + idsDoc + '\nRetourne UNIQUEMENT le JSON.',
    html_skeleton: html,
    css_content:   css,
    task_id:            data.task_id || null,
    resource_name:      resourceName,
    display_fields:     displayFields,
    endpoints:          endpoints,
    // Propager pour Build Payload (génération multi-ressources)
    priority_endpoints: endpoints,
    stores:             stores,
    data_model:         dataModel,
    project_name:       projectName,
    improve_mode:       data.improve_mode || false,
    userRequest:        userRequest,
    mvp_scope:          mvpScope,
    // Conserver le payload original complet pour fallback
    _original_payload:  data
  }
}];

// FRONTEND V5.5 — Multi-ressources + Sécurité DevSecOps
const inp = $input.first().json;
const endpoints  = inp.priority_endpoints || inp.endpoints || [];
const dataModel  = inp.data_model  || {};
const stores     = inp.stores      || {};
var rbacRoles = inp.roles || (inp.artifacts && inp.artifacts.roles) || [];
var rbacPerms = inp.permissions || (inp.artifacts && inp.artifacts.permissions) || {};
var rbacOn = Array.isArray(rbacRoles) && rbacRoles.length > 0;
var _allRolesFront = rbacOn ? (rbacRoles.indexOf('admin')>=0?rbacRoles.slice():['admin'].concat(rbacRoles)) : [];
const mvpScope   = inp.mvp_scope   || '';
const userReq    = inp.userRequest || '';
const projName   = inp.project_name || '';

// ── Logo dynamique ────────────────────────────────────────────────────────
var logoEmoji = '\u26a1';
// project_name en tête : le nom du projet est le signal le plus fort pour le domaine
// (ex: "CrimeStopper" contient "crime" -> palette sécurité)
var pl = (projName + ' ' + mvpScope + ' ' + userReq).toLowerCase().substring(0, 500);
if (pl.includes('trajet') || pl.includes('trip') || pl.includes('voyage') ||
    pl.includes('diaspo') || pl.includes('koli') || pl.includes('colis') ||
    pl.includes('peer') || pl.includes('marketplace')) logoEmoji = '\u2708\ufe0f';
else if (pl.includes('t\u00e2che') || pl.includes('task') || pl.includes('todo')) logoEmoji = '\u2705';
else if (pl.includes('contact') || pl.includes('user') || pl.includes('client')) logoEmoji = '\ud83d\udc65';
else if (pl.includes('produit') || pl.includes('product') || pl.includes('shop')) logoEmoji = '\ud83d\udecd\ufe0f';
else if (pl.includes('commande') || pl.includes('order')) logoEmoji = '\ud83d\udce6';
else if (pl.includes('restaurant') || pl.includes('food')) logoEmoji = '\ud83c\udf7d\ufe0f';
else if (pl.includes('pickup') || pl.includes('livraison') || pl.includes('delivery')) logoEmoji = '\ud83d\udeb2';

// ── Palette de couleurs par domaine métier (déterministe) ──────────────────
// Une palette générique neutre s'applique si aucun mot-clé ne matche (garantit
// un rendu correct même sur un domaine totalement imprévu — condition testée
// en soutenance avec un spec inconnu type TrocSavoir).
// Palette par defaut DETERMINISTE : couleur derivee du nom du projet (teinte HSL),
// pour que chaque app ait des couleurs distinctes meme sans mot-cle de domaine connu.
function _forgeHue(s){ var h=0; s=String(s||'app'); for(var i=0;i<s.length;i++){ h=(h*31 + s.charCodeAt(i))>>>0; } return h % 360; }
function _forgePalette(seed){ var hue=_forgeHue(seed); var h2=(hue+35)%360; return { primary:'hsl('+hue+',62%,45%)', primaryDark:'hsl('+hue+',62%,34%)', secondary:'hsl('+h2+',55%,48%)', success:'#16a34a', danger:'#dc2626', warning:'#d97706' }; }
function _styleProfile(seed){ seed=String(seed||'app'); var n=0; for(var i=0;i<seed.length;i++){ n=(n*131+seed.charCodeAt(i))>>>0; } var radii=[6,10,14,18,4]; var fonts=[{head:'"Georgia",serif',body:'"Segoe UI",system-ui,sans-serif'},{head:'"Trebuchet MS",sans-serif',body:'"Segoe UI",system-ui,sans-serif'},{head:'system-ui,"Segoe UI",sans-serif',body:'"Helvetica Neue",Arial,sans-serif'},{head:'"Palatino Linotype","Book Antiqua",serif',body:'system-ui,sans-serif'},{head:'"Verdana",sans-serif',body:'"Verdana",Geneva,sans-serif'}]; var bgs=['#f0f2f5','#f6f4f1','#eef2f7','#f3f1f6','#eef5f2','#f5f2ee']; var headerBgs=['linear-gradient(135deg,var(--primary),var(--secondary))','linear-gradient(180deg,var(--primary),var(--primary-dark))','var(--primary)','linear-gradient(90deg,var(--primary),var(--primary-dark))']; var buttons=['solid','gradient','outline']; var f=fonts[n%fonts.length]; return { radius:radii[(n>>>3)%radii.length], fontHead:f.head, fontBody:f.body, bg:bgs[(n>>>6)%bgs.length], headerBg:headerBgs[(n>>>9)%headerBgs.length], button:buttons[(n>>>12)%buttons.length] }; }
var style = _styleProfile(projName || mvpScope || userReq || 'app');
var theme = _forgePalette(projName || mvpScope || userReq || 'app');
if (pl.includes('crime') || pl.includes('signalement') || pl.includes('incident') || pl.includes('urgence') || pl.includes('s\u00e9curit\u00e9') || pl.includes('securite')) {
  theme = { primary: '#dc2626', primaryDark: '#991b1b', secondary: '#1e293b', success: '#16a34a', danger: '#b91c1c', warning: '#d97706' };
} else if (pl.includes('koli') || pl.includes('bagage') || pl.includes('kilo') || pl.includes('trajet') || pl.includes('livraison') || pl.includes('transport') || pl.includes('logistique')) {
