function sanitizeStr(s) {
  return String(s || '').replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;').replace(/"/g,'&quot;').replace(/'/g,'&#39;');
}

// ── Grouper endpoints par ressource ──────────────────────────────────────
function getStoreCfg(path) {
  if (!path || path === '/health') return null;
  var seg = path.replace(/^\//, '').split('/')[0];
  for (var res in stores) {
    if (stores[res].store_name === seg) {
      var _reqFromStore = stores[res].required_fields || [];
      var _reqFromModel  = Object.keys(dataModel[res] || {}).filter(function(k){
        return !['id','created_at','updated_at','status'].includes(k);
      });
      var _required = _reqFromStore.length > 0 ? _reqFromStore : _reqFromModel;
      return { res, storeName: seg, required: _required, fields: dataModel[res] || {} };
    }
  }
  var res = seg.replace(/s$/, '');
  var fields = dataModel[res] || {};
  var required = Object.keys(fields).filter(function(k){ return !['id','created_at','updated_at','status'].includes(k); });
  return { res, storeName: seg, required, fields };
}

var resourceMap = {};
endpoints.forEach(function(ep) {
  if (!ep.path || ep.path === '/health') return;
  var cfg = getStoreCfg(ep.path);
  if (!cfg) return;
  var sn = cfg.storeName;
  if (!resourceMap[sn]) resourceMap[sn] = { storeName: sn, required: cfg.required, fields: cfg.fields, getEp: null, postEp: null, deleteEp: null };
  if (ep.method === 'GET' && !ep.path.includes(':')) resourceMap[sn].getEp = ep.path;
  if (ep.method === 'POST') resourceMap[sn].postEp = ep.path;
  if (ep.method === 'DELETE') resourceMap[sn].deleteEp = ep.path;
});
var resources = Object.values(resourceMap);

// FIX : inférer getEp depuis postEp si absent
