resources.forEach(function(r) {
  if (!r.getEp && r.postEp) {
    r.getEp = r.postEp;  // GET /typologies = même path que POST /typologies
  }
  if (!r.deleteEp && r.getEp) {
    r.deleteEp = r.getEp.replace(/\/$/, '') + '/:id';
  }
});

