  if (r.postEp) {
    htmlSections += '\n    <section class="card" id="section-create-' + sn + '">';
    htmlSections += '\n      <h2 class="card-title">\u270f\ufe0f Cr\u00e9er ' + sanitizeStr(label.replace(/s$/, '')) + '</h2>';
    htmlSections += '\n      <form id="form-create-' + sn + '" class="create-form" method="post" autocomplete="off">';
    reqFields.forEach(function(f) {
      var lbl = f.charAt(0).toUpperCase() + f.slice(1).replace(/_/g, ' ');
      var fl = f.toLowerCase();
      var sensitive = ['password','token','secret','key','pin'].some(function(k){ return fl.includes(k); });
      var isNum = r.fields[f] === 'number';
      // Détecter champs FK (se terminent par _id) → générer un select dynamique
      var isFK = f.endsWith('_id') && f !== 'id';
      var refStore = isFK ? f.replace(/_id$/, 's') : null; // ex: trajet_id → trajets
      // Détection de type sémantique pour une meilleure ergonomie de saisie
      var isDate  = /(date|jour|naissance|deadline|echeance|\bddebut\b|\bfin\b)/.test(fl);
      var isEmail = /(email|mail|courriel)/.test(fl);
      var isTel   = /(telephone|\btel\b|phone|mobile|portable|contact)/.test(fl) && !isFK;
      var isLong  = /(description|commentaire|message|motif|contenu|remarque|note[s]?$|detail)/.test(fl) && !isNum;
      // Bornes numériques par sémantique de champ
      var numAttrs = '';
      if (isNum) {
        if (/latitude/.test(fl))       numAttrs = ' min="-90" max="90" step="any"';
        else if (/longitude/.test(fl)) numAttrs = ' min="-180" max="180" step="any"';
        else if (/(prix|montant|cout|tarif|price|amount|salaire)/.test(fl)) numAttrs = ' min="0" step="0.01"';
        else if (/(poids|kilo|quantite|nombre|stock|age|duree)/.test(fl))   numAttrs = ' min="0" step="any"';
      }
      htmlSections += '\n        <div class="form-group">';
      htmlSections += '\n          <label for="field-' + sn + '-' + f + '">' + sanitizeStr(lbl) + '</label>';
      if (isFK && refStore) {
        htmlSections += '\n          <select id="field-' + sn + '-' + f + '" name="' + sanitizeStr(f) + '" class="form-input" required>';
        htmlSections += '\n            <option value="">Chargement...</option>';
        htmlSections += '\n          </select>';
      } else if (isLong) {
        htmlSections += '\n          <textarea id="field-' + sn + '-' + f + '" name="' + sanitizeStr(f) + '" placeholder="' + sanitizeStr(lbl) + '" class="form-input" rows="2" required></textarea>';
      } else {
        var type, ph;
        if (sensitive)   { type = 'password'; ph = sanitizeStr(lbl); }
        else if (isDate) { type = 'date';     ph = ''; }              // sélecteur de date natif
        else if (isEmail){ type = 'email';    ph = 'exemple@domaine.com'; }
        else if (isTel)  { type = 'tel';      ph = '+229 XX XX XX XX'; }
        else if (isNum)  { type = 'number';   ph = sanitizeStr(lbl) + ' (nombre)'; }
        else             { type = 'text';     ph = sanitizeStr(lbl); }
        htmlSections += '\n          <input type="' + type + '"' + (isNum ? numAttrs : '') + ' id="field-' + sn + '-' + f + '" name="' + sanitizeStr(f) + '" placeholder="' + ph + '" class="form-input" required>';
      }
      htmlSections += '\n        </div>';
    });
